window.ScripturaLexicons.BDAG_PART_0197 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-01\" data-source=\"BDAG\" data-search=\"κατευωχέω verbo banquetear-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατευωχέω</td><td>verbo</td><td>banquetear-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-02\" data-source=\"BDAG\" data-search=\"κατεφίσταμαι verbo levantar-se contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατεφίσταμαι</td><td>verbo</td><td>levantar-se contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-03\" data-source=\"BDAG\" data-search=\"κατέχω verbo deter; conservar; ocupar; possuir; manter o rumo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατέχω</td><td>verbo</td><td>deter; conservar; ocupar; possuir; manter o rumo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-04\" data-source=\"BDAG\" data-search=\"κατηγορέω verbo acusar; censurar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατηγορέω</td><td>verbo</td><td>acusar; censurar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-05\" data-source=\"BDAG\" data-search=\"κατηγορία, ας, ἡ substantivo feminino acusação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατηγορία, ας, ἡ</td><td>substantivo feminino</td><td>acusação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-06\" data-source=\"BDAG\" data-search=\"κατήγορος, ου, ὁ substantivo masculino acusador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατήγορος, ου, ὁ</td><td>substantivo masculino</td><td>acusador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-07\" data-source=\"BDAG\" data-search=\"κατήγωρ, ορος, ὁ substantivo masculino acusador; designação do diabo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατήγωρ, ορος, ὁ</td><td>substantivo masculino</td><td>acusador; designação do diabo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-08\" data-source=\"BDAG\" data-search=\"κατήφεια, ας, ἡ substantivo feminino abatimento; melancolia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατήφεια, ας, ἡ</td><td>substantivo feminino</td><td>abatimento; melancolia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-09\" data-source=\"BDAG\" data-search=\"κατηφής, ές adjetivo abatido; cabisbaixo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατηφής, ές</td><td>adjetivo</td><td>abatido; cabisbaixo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-10\" data-source=\"BDAG\" data-search=\"κατηχέω verbo informar; ensinar; instruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατηχέω</td><td>verbo</td><td>informar; ensinar; instruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-11\" data-source=\"BDAG\" data-search=\"κατήχθημεν remissão ver κατάγω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατήχθημεν</td><td>remissão</td><td>ver κατάγω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-12\" data-source=\"BDAG\" data-search=\"κατ’ ἰδίαν remissão ver ἴδιος 5 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατ’ ἰδίαν</td><td>remissão</td><td>ver ἴδιος 5</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-13\" data-source=\"BDAG\" data-search=\"κατιόω verbo ficar enferrujado; corroer-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατιόω</td><td>verbo</td><td>ficar enferrujado; corroer-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-14\" data-source=\"BDAG\" data-search=\"κατισχύω verbo prevalecer; vencer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατισχύω</td><td>verbo</td><td>prevalecer; vencer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-15\" data-source=\"BDAG\" data-search=\"κατοικέω verbo habitar; residir; morar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοικέω</td><td>verbo</td><td>habitar; residir; morar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-16\" data-source=\"BDAG\" data-search=\"κατοίκησις, εως, ἡ substantivo feminino morada; habitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοίκησις, εως, ἡ</td><td>substantivo feminino</td><td>morada; habitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-17\" data-source=\"BDAG\" data-search=\"κατοικητήριον, ου, τό substantivo neutro lugar de habitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοικητήριον, ου, τό</td><td>substantivo neutro</td><td>lugar de habitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-18\" data-source=\"BDAG\" data-search=\"κατοικία, ας, ἡ substantivo feminino habitação; morada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοικία, ας, ἡ</td><td>substantivo feminino</td><td>habitação; morada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-19\" data-source=\"BDAG\" data-search=\"κατοικίζω verbo estabelecer; fazer habitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοικίζω</td><td>verbo</td><td>estabelecer; fazer habitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0197-20\" data-source=\"BDAG\" data-search=\"κατοικτίρω verbo ter piedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατοικτίρω</td><td>verbo</td><td>ter piedade</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0197-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατευωχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατευωχέω</span> (<span class=\"greek\">εὐωχέομαι</span> ‘banquetear-se suntuosamente’; Hdt. e outros; inscrições [KClinton, Hesperia 49, ’80, p. 263, linha 8, num contexto fragmentário, IV a.C.]; Philo, Joseph.) banquetear-se, na voz média, <span class=\"greek\">κατευωχούμενοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:13</a>, variante de leitura.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατεφίσταμαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατεφίσταμαι</span> (veja <span class=\"greek\">ἐφίστημι</span>), 2º aoristo <span class=\"greek\">κατεπέστην</span> (hapax legomenon), levantar-se <span class=\"greek\">τινί</span> contra alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:12</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατέχω</span> imperfeito <span class=\"greek\">κατεῖχον</span>; futuro <span class=\"greek\">καθέξω</span> LXX, 3ª pessoa do plural <span class=\"greek\">κατασχήσουσι</span> (JosAs 16 [p. 64, 18 Bat. e códice A]); 2º aoristo <span class=\"greek\">κατέσχον</span>. Passiva: futuro, 2ª pessoa do plural <span class=\"greek\">κατασχεθήσεσθε</span>, Ruth 1:13; aoristo, 3ª pessoa do singular <span class=\"greek\">κατεσχέθη</span>, LXX (veja <span class=\"greek\">ἔχω</span>; Hom.+). Transitivo em todas as acepções seguintes, exceto na 7. ① Impedir a realização de alguma coisa ou torná-la ineficaz, impedir, dificultar, restringir. ⓐ Reter alguém, impedindo-o de partir, segurar, deter, impedir a partida (Hom. e outros; BGU 1205, 27 [28 a.C.]; 37, 6 [50 d.C.]; PFay 109, 11; Gen 24:56; cf. Jos., Ant. 7, 76; Just., A I, 45, 1), Hs 9, 11, 6. <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">ἐβουλόμην</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">κ</span>., a quem eu desejava manter comigo, Phlm 13. Seguido pelo genitivo do infinitivo com artigo (B-D-F § 400, 4): <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄχλοι</span> <span class=\"greek\">κατεῖχον</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:42</a>. ⓑ Conter, reprimir <span class=\"greek\">τὶ</span>, alguma coisa (<span class=\"greek\">γέλωτα</span> X., Cyr. 2, 2, 1; Chariton 3, 7, 4 <span class=\"greek\">τ</span>. <span class=\"greek\">λύπην</span>; WCrum, Coptic Ostraca p. 4, 522 = Dssm., LO 260 [LAE 306] = PGM II 233, nº O 1, 1–3 <span class=\"greek\">Κρόνος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">κατέχων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θυμὸν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span>, <span class=\"greek\">κάτεχε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυμὸν</span> <span class=\"greek\">Ὡρι</span>; cf. II, 7, 935f, p. 41; Jos., Vi. 233 <span class=\"greek\">τ</span>. <span class=\"greek\">ὀργήν</span>): <span class=\"greek\">τ</span>. <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀδικίᾳ</span>, sufocar a verdade pela injustiça ou iniquidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:18</a> (cf. JFitzmyer, Ro [AB], ’93, 278; mas veja 6 abaixo). ⓒ Impedir alguém de exercer poder, restringir, refrear (Thu. 6, 29, 3; Appian, Bell. Civ. 2, 149 §622 <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαίμονος</span> <span class=\"greek\">κατέχοντος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέλαγος</span> = o poder divino manteve o mar contido até Alexandre alcançar a outra margem; PGiss 70, 3 [II d.C.] <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀναγραφὴ</span> <span class=\"greek\">κατέσχεν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">ἕκτης</span>): <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κατέξω</span> <span class=\"greek\">τ</span>̣<span class=\"greek\">ὰ</span> [<span class=\"greek\">προς</span>]|<span class=\"greek\">τεταγμένα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπεικίμ</span>̣[<span class=\"greek\">εν</span>]<span class=\"greek\">α</span>, para que eu não atrasasse (a execução) das instruções e ordens, AcPl Ha 7, 14f. <span class=\"greek\">τὸ</span> <span class=\"greek\">κατέχον</span> (Themistocl., Ep. 13, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:6</a>, e <span class=\"greek\">ὁ</span> <span class=\"greek\">κατέχων</span>, versículo 7, significam aquilo que restringe e aquele que restringe, isto é, o que impede por enquanto o adversário de Deus de manifestar oposição aberta a Deus. Na tentativa de definir <span class=\"greek\">κ</span>. mais especificamente aqui, muitos intérpretes seguiram a exegese da Igreja antiga (Tertuliano) e entenderam <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. como o Império Romano e <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. como o imperador (OBetz, NTS 9, ’63, 276–91). Uma interpretação alternativa, tão antiga quanto Teodoro de Mopsuéstia, embora sem aceitação continuada, identifica <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. com a pregação dos missionários cristãos e <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. com o apóstolo Paulo (assim OCullmann, Dodd Festschr. ’56, 409–21). Essas e outras tentativas de limitar mais precisamente o significado dessas expressões em 2 Th suscitam ceticismo pela insuficiência de dados textuais (o versículo 5 parece pressupor informações partilhadas no interior da comunidade). A ideia de uma restrição temporária das forças do inferno (cf. Rtzst., Poim. 27, oração egípcia tardia 6, 4, Hórus como <span class=\"greek\">κατέχων</span> <span class=\"greek\">δράκοντα</span> = PGM 4, 994f; cf. 2770 <span class=\"greek\">Μιχαὴλ</span> … <span class=\"greek\">κατέχων</span>, <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">καλέουσι</span> <span class=\"greek\">δράκοντα</span> <span class=\"greek\">μέγαν</span>) não parece desempenhar papel algum aqui.—WBousset, D. Antichrist 1895; NFreese, StKr 93, 1921, 73–77; VHartl, ZKT 45, 1921, 455–75; WSchröder, D. 2. Thess. 1929, 8–15; DBuzy, RSR 24, ’34, 402–31; OCullmann, RThAM 1, ’38, 26–61; JSchmid, TQ 129, ’49, 323–43; OBetz, NTS 9, ’63, 276–91. Diferentemente, CGiblin, Threat to Faith ’67, 167–242, entende uma força hostil. Veja também JTownsend, SBLSP 19, ’80, 233–46; RAus, JBL 96, ’77, 537–53; New Docs 3, 28. ⓓ Reter algo deliberadamente, guardar em segredo <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σοφὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">βουλήν</span>, manter o seu sábio desígnio em segredo, Dg 8:10. ② Aderir firmemente a tradições, convicções ou crenças, conservar, manter-se fiel (cf. o sentido literal <span class=\"greek\">λαμπάδας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">χερσίν</span> ParJer 3:2). ⓐ Guardar na memória (Theophr., Char. 26, 2, uma palavra de Homero): <span class=\"greek\">εἰ</span> <span class=\"greek\">κατέχετε</span>, se o conservais firmemente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:2</a>. ⓑ Reter firmemente, preservar com fidelidade (X., Symp. 8, 26 <span class=\"greek\">τ</span>. <span class=\"greek\">φιλίαν</span>; TestJud 26:1 <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδούς</span>): <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:15</a>; <span class=\"greek\">τὰς</span> <span class=\"greek\">παραδόσεις</span>, guardar as tradições, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:2</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">καλόν</span>, reter o que é bom, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:21</a>; Agr 11; <span class=\"greek\">τὴν</span> <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">βεβαίαν</span> <span class=\"greek\">κ</span>., conservar firme a confiança, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:6</a>; cf. versículo 14. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁμολογίαν</span> <span class=\"greek\">ἀκλινῆ</span>, 10:23. ③ Manter em sua posse, possuir (Ps.-Aristot., Mirabilia 159; 160; Polyb. 1, 2, 3; IMagnMai 105, 51 [II a.C.] <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἔχωσιν</span> <span class=\"greek\">κατέχωσίν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καρπίζωνταί</span> <span class=\"greek\">τε</span>; Ezk 33:24; Da 7:18, 22; Ath. 8:3), <span class=\"greek\">τὶ</span>, alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:38</a>, variante de leitura; <span class=\"greek\">ὡς</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κατέχοντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:10</a> (DMealand [ZNW 67, ’76, 277–79] cita Ps.-Crates Ep. 7 Hercher = p. 58 nº 7, 8 Malherbe: <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πάντ</span>’ <span class=\"greek\">ἔχομεν</span>, <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πάντ</span>’ <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἔχετε</span>). Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:30</a>. ④ Manter dentro de limites que restringem, confinar. ⓐ Na prisão: manter preso, confinar (PFlor 61, 60; BGU 372 I, 16; Gen 39:20; Philo, Leg. All. 3, 21), na passiva <span class=\"greek\">Χριστιανοὶ</span> <span class=\"greek\">κατέχονται</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φρουρᾷ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span>, os cristãos são confinados no mundo como numa prisão, Dg 6:7. ⓑ Pela lei: <span class=\"greek\">ἀποθανόντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">κατειχόμεθα</span>, tendo morrido para aquilo que nos prendia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:6</a> (cf. PAmh 97, 17 <span class=\"greek\">οὐ</span> <span class=\"greek\">κατασχεθήσομαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑποσχέσει</span>; PRyl 117, 13). ⓒ Pela doença (Diod S 4, 14, 5; Philo, Op. M. 71, Congr. Erud. Grat. 138; PSI 299, 3 <span class=\"greek\">κατεσχέθην</span> <span class=\"greek\">νόσῳ</span>; ativa, Jer 13:21; Jos., Vi. 48), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:38</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:4</a>, variante de leitura. ⑤ Ocupar um lugar como próprio, tomar posse, ocupar (Hdt. 5, 72 e outros; PAmh 30, 26 [II a.C.] <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span>): <span class=\"greek\">τὸν</span> <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">τόπον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:9</a> (cf. Philosoph. Max. 491, 69 <span class=\"greek\">τὸν</span> <span class=\"greek\">κάλλιστον</span> <span class=\"greek\">κατέχουσι</span> <span class=\"greek\">τόπον</span>; Jos., Ant. 8, 104). Cf. GPt 5:15.—AcPl Ha 5, 28 [<span class=\"greek\">κατ</span>]<span class=\"greek\">ε</span>̣<span class=\"greek\">ῖ</span>̣<span class=\"greek\">χεν</span> <span class=\"greek\">αὐτὰς</span> <span class=\"greek\">ἔκστασις</span> talvez signifique o assombro as dominou. ⑥ Reivindicar, termo técnico jurídico, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:18</a> (a ideia é que se reivindica a verdade, mas ela é negada na prática; cf. versículos 22f; veja FDanker, em Gingrich Festschr. 93. Para outra interpretação, veja 1b acima). ⑦ Manter o rumo, termo técnico náutico, intransitivo (Hdt. 7, 188 <span class=\"greek\">κατέσχε</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰγιαλόν</span>; Dicaearchus, Fgm. 85 W. <span class=\"greek\">εἰς</span> <span class=\"greek\">Δῆλον</span> <span class=\"greek\">κατέσχε</span>; Polyb. 1, 25, 7; Philostrat., Vi. Apoll. 4, 13 p. 133, 5; 5, 18 p. 178, 13; cf. Jos., Ant. 1, 204): <span class=\"greek\">κατεῖχον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰγιαλόν</span>, dirigiram-se para a praia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:40</a>. ⑧ Talvez no sentido de determinar (cf. <span class=\"greek\">προσέχω</span> 2c): <span class=\"greek\">κατεχόντων</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ἀπέθανεν</span>, AcPt Ox 849, 2f; veja as notas do editor.—M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατηγορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατηγορέω</span> imperfeito <span class=\"greek\">κατηγόρουν</span>; futuro <span class=\"greek\">κατηγορήσω</span>; 1º aoristo <span class=\"greek\">κατηγόρησα</span>; aoristo passivo, 3ª pessoa do singular <span class=\"greek\">κατηγορήθη</span> (AscIs 3:5) (Trag., Hdt.+; empréstimo no rabínico), geralmente ‘falar contra’. ① Quase sempre como termo técnico jurídico: formular acusações em juízo. ⓐ Perante juiz humano: contra alguém, <span class=\"greek\">τινά</span>, alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:2</a>, variante de leitura; <span class=\"greek\">τινός</span> (Hdt., Aristoph., Pla. e outros, também SIG 173, 37; 780, 8; PPetr III, 21g, 14; PEdgar 33 [= Sb 6739], 4; AscIs 3:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:7</a>; 11:54, variante de leitura; 23:2, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:5</a>. <span class=\"greek\">τί</span> <span class=\"greek\">τινος</span>, acusar alguém de alguma coisa (Trag., X., Demosth. e outros, também 1 Macc 7:25): <span class=\"greek\">κατηγόρουν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πολλά</span>, apresentavam muitas acusações contra ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:3</a> (quanto a <span class=\"greek\">πολλά</span>, cf. PLond 893, 12 [40 d.C.] <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>.); cf. versículo 4. <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔθνους</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">τι</span> <span class=\"greek\">κατηγορεῖν</span>, não porque tivesse alguma acusação a apresentar contra meu próprio povo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:19</a>. A esta acepção também pode pertencer <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τούτων</span>, <span class=\"greek\">ὧν</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">κατηγοροῦμεν</span> <span class=\"greek\">αὐτοῦ</span>, acerca de todas essas coisas das quais o acusamos, 24:8; de modo semelhante 25:11, caso se trate de atração do relativo <span class=\"greek\">ὡν</span> = <span class=\"greek\">τούτων</span> <span class=\"greek\">ἅ</span>. Mas também é possível interpretá-lo como duplo genitivo (cf. Demosth. 21, 5 <span class=\"greek\">παρανόμων</span> <span class=\"greek\">ἔμελλον</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κατηγορεῖν</span>; Dositheus 68, 2 <span class=\"greek\">βίας</span> <span class=\"greek\">σου</span> <span class=\"greek\">κατηγορῶ</span>).—Também <span class=\"greek\">τινὸς</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Thu. 8, 85, 2; X., Hell. 1, 7, 2; Jos., Ant. 13, 104), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:13</a>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> (X., Hell. 1, 7, 9), com genitivo ou, no caso de atração (veja acima), acusativo da coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:14</a>. Uso absoluto (OGI 218, 95 [III a.C.]; POxy 237 VIII, 21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:2</a>, 19. Na passiva, ser acusado <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, por alguém (Thu. 1, 95, 3 <span class=\"greek\">ἀδικία</span> <span class=\"greek\">κατηγορεῖτο</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἑλλήνων</span>; 2 Macc 10:13; Philo, Mut. Nom. 206), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:12</a>. <span class=\"greek\">τί</span> <span class=\"greek\">κατηγορεῖται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰουδαίων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:30</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηγορούμενος</span>, o acusado (PCairMasp 63, 2), 25:16. ⓑ Perante o tribunal de Deus: <span class=\"greek\">κατηγορήσω</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πατέρα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:45a</a> (sobre a construção com <span class=\"greek\">πρός</span>, cf. 1 Macc 7:6; 2 Macc 10:13). <span class=\"greek\">ὁ</span> <span class=\"greek\">κατήγωρ</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηγορῶν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:10</a> (para o acusativo, veja PLond I, 41, 10 p. 28 [161 a.C.] <span class=\"greek\">ὁ</span> <span class=\"greek\">βουκόλος</span> <span class=\"greek\">κατηγόρησεν</span> <span class=\"greek\">αὐτάς</span>). Substantivado, <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηγορῶν</span>, o acusador (cf. Jos., C. Ap. 2, 137), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:45b</a>. ② Sem conotação jurídica, acusar, censurar (X., Mem. 1, 3, 4; Aelian, VH 9, 17; Herodian 6, 9, 1; Philo, Plant. 80; SB V/2, 7835, 17 [New Docs 1, 28]): acerca de Jó, <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">κατηγορεῖ</span>, ele acusa a si mesmo, 1 Cl 17:4. Em uso absoluto, acerca de pensamentos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:15</a>.—B. 1439. DELG s.v. <span class=\"greek\">ἀγορά</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατηγορία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατηγορία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior e os dois seguintes; Hdt.+; inscrições; POxy 237 VIII, 7; Mitt-Wilck II/2, 68, 19f [restaurado]; Philo; Jos., Ant. 2, 49, C. Ap. 2, 137; Just., A II, 2, 7; Ath.; quanto à correção deste termo, veja <span class=\"greek\">καταλαλία</span>; empréstimo no rabínico): acusação; <span class=\"greek\">τίνα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φέρετε</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> <span class=\"greek\">τούτου</span>;, que acusação apresentais contra este homem?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:29</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">παραδέχεσθαι</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, admitir uma acusação contra alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:19</a> (<span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, como Isocr. 5, 147; SIG 704 F 7; 705, 32). <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κατηγορίαν</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:11</a>, variante de leitura; cf. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κατηγορίαν</span> <span class=\"greek\">τινός</span>, 8:4 D; <span class=\"greek\">εὑρεῖν</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:7</a>, variante de leitura. Com genitivo do conteúdo da acusação (Demosth. 18, 279; Philo, Fuga 36): <span class=\"greek\">κ</span>. <span class=\"greek\">ἀσωτίας</span>, acusação de devassidão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:6</a>.—DELG s.v. <span class=\"greek\">ἀγορά</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατήγορος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατήγορος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja os dois verbetes anteriores; Soph., Hdt.; inscrições, papiros; Pr 18:17; 2 Macc 4:5; Philo; Jos., Bell. 4, 339, C. Ap. 2, 132; Tat.; Ath. 2:3; Hippol.; <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστιανισμοῦ</span> Orig. C. Cels. 1, 64, 31): acusador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:10</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:30</a>, 35; 24:8, variante de leitura; 25:16, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:10</a>, variante de leitura; IMg 12 (Pr 18:17).—DELG s.v. <span class=\"greek\">ἀγορά</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατήγωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατήγωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (veja os três verbetes anteriores; empréstimo no rabínico, e não modificação hebraica [Bousset, Offb. Joh. 6 1906, 342] nem aramaica [W-S. §8, 13 p. 85f] do grego <span class=\"greek\">κατήγορος</span>, mas antes formação coloquial decorrente do fato de que o genitivo plural é <span class=\"greek\">κατηγόρων</span>, quer a palavra pertença à segunda, quer à terceira declinação. Essa forma também se encontra em PGM 10, 25. Cf. Dssm., LO 72f [LAE 90f]; Rdm. 2 19; Mlt-H. 127f; B-D-F § 52; Psaltes, 175; ADebrunner, GGA 1926, 137ff): acusador, designação do diabo (Billerb. I 141f); <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀδελφῶν</span> <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:10</a>.—DELG s.v. <span class=\"greek\">ἀγορά</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατήφεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατήφεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete seguinte; Hom. e outros; Dionys. Hal.; Plut.; Philo, Spec. Leg. 3, 193; Jos., Ant. 13, 406; 19, 260): melancolia, abatimento (Chariton 6, 8, 3; 7, 3, 3; cf. Plut., Mor. 528e <span class=\"greek\">τ</span>. <span class=\"greek\">κατήφειαν</span> <span class=\"greek\">ὁρίζονται</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">κάτω</span> <span class=\"greek\">βλέπειν</span> <span class=\"greek\">ποιοῦσαν</span>, ‘definem <span class=\"greek\">κ</span>. como tristeza que faz baixar o olhar’. De maneira semelhante, Etym. Mag. 496, 53): <span class=\"greek\">μετατραπήτω</span> … <span class=\"greek\">ἡ</span> <span class=\"greek\">χαρὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>., transforme-se … a vossa alegria em abatimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:9</a>.—DELG s.v. <span class=\"greek\">κατηφής</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατηφής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατηφής</span>, <span class=\"greek\">ές</span> (veja o verbete anterior; Hom. e outros; POxy 471, 92; Acta Alex. VII A, 92f; Wsd 17:4; Jos., Ant. 2, 55): abatido, cabisbaixo; <span class=\"greek\">τί</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰδέᾳ</span>;, por que pareces tão abatido?, Hv 1, 2, 3; <span class=\"greek\">τί</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">στυγνὸς</span> <span class=\"greek\">κ</span>., <span class=\"greek\">κύριε</span>;, por que estás tão triste e cabisbaixo, senhor?, AcPl Ha 7, 30. A palavra é restaurada em 8, 8: [<span class=\"greek\">κατηφ</span>]<span class=\"greek\">ὲ</span>̣<span class=\"greek\">ς</span> <span class=\"greek\">ἀποθέμενον</span>, mas <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span>, como na passagem duplicada de AcPl BMM recto 7 (veja <span class=\"greek\">λύπη</span>), também se ajusta. Embora <span class=\"greek\">κατηφής</span> apareça no contexto imediatamente próximo de Ha, o papiro também utiliza <span class=\"greek\">λύπη</span>.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατηχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατηχέω</span> 1º aoristo <span class=\"greek\">κατήχησα</span>, passiva <span class=\"greek\">κατηχήθην</span>; perfeito passivo <span class=\"greek\">κατήχημαι</span> (palavra tardia; PStras 41, 37 [III d.C.]; não consta na LXX, mas ocorre em ParJer 5:19; Philo, Joseph.); geralmente ‘comunicar’. ① Transmitir uma comunicação recebida, relatar, informar (Jos., Vi. 366 <span class=\"greek\">αὐτός</span> <span class=\"greek\">σε</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κατηχήσω</span> = ‘eu mesmo te darei muitas informações’); na passiva, ser informado, saber (Philo, Leg. ad Gai. 198; Ps.-Plut., Fluv. 7, 2; 8, 1; 17, 1 <span class=\"greek\">κατηχηθεὶς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">συμβεβηκότων</span>; PPrinc II, 20, 1 [II d.C.]): <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐπιγνῷς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">κατηχήθης</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀσφάλειαν</span> (= <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">κ</span>.), para que conheças a certeza das coisas que ouviste ou das quais foste informado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:4</a> (assim Zahn, JWeiss, EKlostermann; FVogel, NKZ 44, ’33, 203–5; Beyer, RSV; provavelmente com referência às variações nos relatos ou narrativas acerca da vida de Jesus; veja <span class=\"greek\">ἀσφάλεια</span> 2; outros preferem a acepção 2a). Em contexto forense: <span class=\"greek\">κατηχήθησαν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">ὅτι</span>, foram informados a teu respeito que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:21</a>; cf. versículo 24. ② Ensinar, instruir (Lucian, Jupp. Trag. 39; Ps.-Lucian, Asin. 48; em nossa literatura, apenas acerca de instrução em assuntos teológicos. O substantivo <span class=\"greek\">κατήχησις</span> normalmente se refere a ‘instrução’ [LAlexander, The Preface to Luke’s Gospel ’93, 139; veja também 141f]). ⓐ Em sentido geral, <span class=\"greek\">τινά</span>, alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:19</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηχῶν</span>, o mestre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:6b</a>. Na passiva (Ps.-Lucian, Philopatr. 17, acerca do ensino sobre Deus: <span class=\"greek\">κατηχούμενος</span> <span class=\"greek\">πείθου</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span>): <span class=\"greek\">κατηχούμενος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, instruído pela lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:18</a>. Com acusativo do que se ensina: <span class=\"greek\">κατηχημένος</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, instruído no caminho do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:25</a> (cf. Iren. 3, 12, 7 [Harv. II 61, 2f]; Hippol., Ref. 6, 36, 2]). <span class=\"greek\">ὁ</span> <span class=\"greek\">κατηχούμενος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, aquele que é instruído na palavra (cristã), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:6a</a> (B-D-F § 159, 1. BWeiss, HHoltzmann, FHauck, Rengstorf, Goodsp., NRSV e outros preferem esta acepção para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:4</a> [mas veja a acepção 1 acima]: para que conheças a verdade das coisas que te foram ensinadas. Veja <span class=\"greek\">παρακολουθέω</span> 3). ⓑ No sentido específico de instrução cristã básica destinada a novos convertidos, ministrar instrução, 2 Cl 17:1.—PCarrington, The Primitive Christian Catechism ’40; CDodd em NT Essays (volume em memória de TWManson) ’59, 106–18.—DELG s.v. <span class=\"greek\">ἠχή</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατήχθημεν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">κατήχθημεν</span> veja <span class=\"greek\">κατάγω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατ’ ἰδίαν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Remissão</div><p class=\"entry-text\"><span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span> veja <span class=\"greek\">ἴδιος</span> 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατιόω</span> (veja <span class=\"greek\">ἰός</span> 2; Sir 12:11), perfeito passivo, 3ª pessoa do singular <span class=\"greek\">κατίωται</span>; a passiva tem sentido intransitivo: ficar enferrujado, embaçado, corroído (Strabo 16, 2, 42; Epict. 4, 6, 14), acerca de ouro e prata (cf. EpJer 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:3</a>.—DELG 4 <span class=\"greek\">ἰός</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατισχύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατισχύω</span> (veja <span class=\"greek\">ἰσχύω</span>), imperfeito <span class=\"greek\">κατίσχυον</span>; futuro <span class=\"greek\">κατισχύσω</span>; 1º aoristo <span class=\"greek\">κατίσχυσα</span> (em vários sentidos relativos à demonstração de força: ‘ser forte, poderoso, obter ascendência’; Soph.+; frequente em escritores posteriores e na LXX; En 104:6; PsSol 2:7; Test12Patr, EpArist; Jos., Ant. 14, 357, mas quase ausente das inscrições e papiros [PGM 13, 797]); intransitivo. ① Ter força ou capacidade para obter vantagem, dominar, prevalecer, em uso absoluto (Polyb. 11, 13, 3; Ex 17:11; En 104:6): <span class=\"greek\">κατίσχυον</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">φωναὶ</span> <span class=\"greek\">αὐτῶν</span>, prevaleceram as vozes deles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:23</a> (Antig. Car. 152 <span class=\"greek\">κατίσχυκεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φήμη</span>). Seguido de infinitivo: ser capaz, estar em condições, 21:36. ② Ter capacidade de derrotar, vencer, com genitivo (Dio Chrys. 12 [13], 4 e outros; Aelian, HA 5, 19; Wsd 7:30; Jer 15:18; Jos., Bell. 2, 464 <span class=\"greek\">κατισχύσας</span> <span class=\"greek\">πλειόνων</span> = vencedor de força superior; TestReub 4:11): <span class=\"greek\">πύλαι</span> <span class=\"greek\">ᾅδου</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κατισχύσουσιν</span> <span class=\"greek\">αὐτῆς</span> (isto é, <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:18</a> (veja <span class=\"greek\">πύλη</span> a); <span class=\"greek\">πάσης</span> <span class=\"greek\">πονηρίας</span>, Hv 2, 3, 2. <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, triunfar sobre as obras do diabo, Hm 12, 6, 4.—DELG s.v. <span class=\"greek\">ἰσχύς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοικέω</span> (veja os quatro verbetes seguintes); futuro <span class=\"greek\">κατοικήσω</span>; 1º aoristo <span class=\"greek\">κατῴκησα</span>; infinitivo perfeito <span class=\"greek\">κατῳκηκέναι</span> (Just., D. 79, 2); aoristo passivo, subjuntivo <span class=\"greek\">κατοικηθῶ</span>, LXX (veja <span class=\"greek\">οἰκέω</span>; Soph., Hdt.+). ① Viver numa localidade por qualquer período de tempo, viver, habitar, residir, estabelecer-se, intransitivo. ⓐ Com o lugar indicado por <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (X., An. 5, 3, 7; IHierapJ 212 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἱεραπόλει</span> <span class=\"greek\">κατοικούντων</span> <span class=\"greek\">Ἰουδαίων</span>; PMagd 25, 2 [221 a.C.]; PTebt 5, 180; Lev 23:42; Gen 14:12; Philo, Sobr. 68; Jos., Vi. 31; PMert 63, 9): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:20</a> (cf. Ps 68:26); 2:5, variante de leitura (para <span class=\"greek\">εἰς</span>, veja abaixo); 7:2, 4a, 48; 9:22; 11:29; 13:27; 17:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:12</a>; B 11:4; IEph 6:2; Hs 3:1. Também usado com <span class=\"greek\">εἰς</span> e acusativo (Ps.-Callisth. 1, 38, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">φθαρτὰ</span> <span class=\"greek\">σώματα</span> <span class=\"greek\">ἀθανάτων</span> <span class=\"greek\">ὀνόματα</span> <span class=\"greek\">κατοικεῖ</span>; escólio de Soph., Trach. 39 p. 281 Papag.; B-D-F § 205; Rob. 592f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; 4:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:5</a>; 7:4b. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τείχη</span>, Hs 8, 7, 3; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πύργον</span>, 8, 8, 5; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐρχόμενον</span>, Hs 4:2. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, viver sobre a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a>; 6:10; 8:13; 11:10ab; 13:8, 14ab; 14:6, variante de leitura; 17:8. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, habitar toda a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξένης</span> (isto é, <span class=\"greek\">χώρας</span>), Hs 1:6; <span class=\"greek\">ποῦ</span>, <span class=\"greek\">ὅπου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13a</a>b. Em uso absoluto (CB I/2, 461, números 294 e 295 <span class=\"greek\">οἱ</span> <span class=\"greek\">κατοικοῦντες</span> <span class=\"greek\">Ῥωμαῖοι</span>): <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> (subentenda-se <span class=\"greek\">ἐκεῖ</span>) <span class=\"greek\">κατοικούντων</span> <span class=\"greek\">Ἰουδαίων</span>, por todos os judeus que moram ali, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:12</a>. ⓑ Em relação à habitação de seres humanos por Deus, Cristo, o Espírito Santo e outros seres transcendentes, virtudes etc. (cf. Wsd 1:4; TestDan 5:1, TestJos 10:2f): <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span>, Deus habita em nós, B 16:8; acerca de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:17</a>; cf. Hm 3:1; acerca do Espírito Santo, Hm 5, 2, 5; 10, 2, 5; Hs 5, 6, 5; <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μακροθυμίᾳ</span> <span class=\"greek\">κ</span>., m 5, 1, 3. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεότητος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:9</a>; cf. 1:19; <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">κ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:13</a> (cf. Is 32:16). <span class=\"greek\">ἡ</span> <span class=\"greek\">μακροθυμία</span> <span class=\"greek\">κατοικεῖ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἐχόντων</span>, a paciência habita com os que têm fé, Hm 5, 2, 3. Acerca do domínio ou possessão por espíritos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:26</a> (<span class=\"greek\">κ</span>. <span class=\"greek\">ἐκεῖ</span>, como Palaeph. 39 p. 44, 4). ② Tornar alguma coisa habitação ou morada por estar nela, habitar <span class=\"greek\">τὶ</span>, alguma coisa (Demosth., Ep. 4, 7 <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰνδικὴν</span> <span class=\"greek\">χώραν</span>; Ps.-Aristot., Mirabilia 136; SIG 557, 17 <span class=\"greek\">τ</span>. <span class=\"greek\">Ἀσίαν</span>; PMagd 9, 1 [III a.C.]; PTor 4, 8 [117 a.C.] <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">πόλιν</span>; Gen 13:7; Ezk 25:16; Philo, Leg. All. 3, 2; Jos., Vi. 27 <span class=\"greek\">Δαμασκόν</span>): <span class=\"greek\">Ἰερουσαλήμ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:19</a>; 2:14; 4:16. Cf. 2:9 (cf. Diod S 18, 11, 2 <span class=\"greek\">Μεσσήνιοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἀκτὴν</span> <span class=\"greek\">κατοικοῦντες</span>); 9:32, 35; 19:10, 17. <span class=\"greek\">οἱ</span> <span class=\"greek\">κατοικοῦντες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, os habitantes da terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a>, variante de leitura; 17:2; <span class=\"greek\">κ</span>. <span class=\"greek\">πόλεις</span> (Hdt. 7, 164), Dg 5:2; <span class=\"greek\">οἰκίας</span> <span class=\"greek\">πηλίνας</span>, 1 Cl 39:5 (Job 4:19); <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, Hs 9, 17, 1. Acerca de Deus, <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">ναόν</span>, aquele que habita no templo (cf. Jos., Bell. 5, 458f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:21</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:5</a>, variante de leitura.—DELG s.v. <span class=\"greek\">οἶκος</span> II C. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοίκησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοίκησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior e os três seguintes; Thu. e outros; PLond 1708, 111; IMaronIsis 34; LXX; En; Jos., Ant. 6, 321, C. Ap. 2, 34; 35): moradia, alojamento, habitação; <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μνήμασιν</span>, viver entre os túmulos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:3</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πύργῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span>, Hv 3, 8, 8. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτῶν</span> (cf. Gen 10:30) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πύργον</span>, encontraram morada na torre, Hs 8, 7, 5; 8, 9, 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικητήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοικητήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja os dois verbetes anteriores e os dois seguintes; o sufixo -<span class=\"greek\">τηριον</span> indica frequentemente um ‘lugar onde algo ocorre’ [B-D-F § 109, 9]) (LXX; Cat. Cod. Astr. VIII/1 p. 189, 10; inscrição cristã CIA III 3508.—O adjetivo <span class=\"greek\">κατοικητήριος</span> em Soranus p. 37, 16): morada, lugar de habitação; <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δαιμονίων</span>, tornou-se morada de espíritos malignos, isto é, eles tomaram posse dela, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:2</a> (cf. Jer 9:10 <span class=\"greek\">κ</span>. <span class=\"greek\">δρακόντων</span>). Acerca dos cristãos: <span class=\"greek\">συνοικοδομεῖσθε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, sois edificados juntamente para morada de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:22</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span>, a habitação do coração, um templo de Deus, B 6:15; cf. 16:7f.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοικία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>: morada, habitação (veja os três verbetes anteriores e o seguinte; Polyb. 2, 32, 4; Diod S 18, 7, 7; Strabo 5, 4, 8; Mitt-Wilck. II/2, 31 I, 23 [116 a.C.]; Sb 5620, 3; inscrições [veja New Docs 4, 142]; 1 Esdr 9:12, 37; 1 Macc 1:38; 2 Macc 3:39; Jos., Ant. 10, 223; 18, 37), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πύργον</span>, na torre, Hs 8, 7, 3; 8, 8, 2f; 8, 9, 4; 8, 10, 1; 4; 9, 13, 5; cf. 8, 3, 4; 8, 6, 3; 6.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοικίζω</span> (veja os quatro verbetes anteriores); futuro <span class=\"greek\">κατοικιῶ</span>; 1º aoristo <span class=\"greek\">κατῴκισα</span>. Na passiva: futuro <span class=\"greek\">κατοικισθήσομαι</span>; aoristo <span class=\"greek\">κατωκίσθην</span>; perfeito <span class=\"greek\">κατῴκισται</span> (todos na LXX): fazer habitar, estabelecer, instalar (assim Hdt. e outros; POxy 705, 24; LXX; EpArist; Jos., Ant. 1, 110 <span class=\"greek\">εἰς</span>; 11, 19 <span class=\"greek\">ἐν</span>), acerca do Espírito: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">κατῴκισεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span>, o Espírito que (Deus) fez habitar em nós, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:5</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ταύτῃ</span>, Hm 3:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κατῴκισεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σάρκα</span>, Deus fez o Espírito habitar na carne, Hs 5, 6, 5.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0197-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατοικτίρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κατοικτίρω</span> 1º aoristo, subjuntivo, 1ª pessoa do plural <span class=\"greek\">κατοικτίρωμεν</span>, 4 Macc 8:20; particípio <span class=\"greek\">κατοικτίρας</span>, 4 Macc 12:2; infinitivo <span class=\"greek\">κατοικτίραι</span> ou <span class=\"greek\">κατοικτεῖραι</span> (veja <span class=\"greek\">οἰκτίρω</span>; Soph., Hdt.+; 4 Macc): ter piedade <span class=\"greek\">τὶ</span>, de alguma coisa (Alciphron 3, 39, 3); <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡλικίαν</span> (cf. 4 Macc 8:20 <span class=\"greek\">τὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μητρὸς</span> <span class=\"greek\">γῆρας</span>), MPol 3, 1.—DELG s.v. <span class=\"greek\">οἶκτος</span>.</p></section></article>"};
